// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io/

let spotColors = ["#0077e1", "#f5d216", "#fc3503"];

function setup() {
  createCanvas(500, 500);
  // noLoop() removed for animation
  stroke("#0a0a0a");
  strokeCap(PROJECT);
}

function draw() {
  background("#f7f3f2");

  let n = random([4, 6, 8, 10]);
  let s = width/n;
  strokeWeight(Math.max(0.1, Math.abs(s/12)));
  let u = s/3;

  let xSpot = floor(random(n))*s;
  let ySpot = floor(random(n))*s;

  for (let x = 0; x < width; x += (Math.max(0.001, Math.abs(s)) || 1)) {
    for (let y = 0; y < height; y += (Math.max(0.001, Math.abs(s)) || 1)) {
      push();
      translate(x, y);

      if ((x == xSpot) && (y == ySpot)) {
        line(u, 0, 0, u);
        line(2*u, 0, 3*u, u);
        line(0, 2*u, u, 3*u);
        line(3*u, 2*u, 2*u, 3*u);

        noStroke();
        fill(random(spotColors));
        circle(s/2, s/2, u*sqrt(2));
      } else {
        let r = random(2);
        if (r < 1) {
          line(0, 2*u, u, 3*u);
          line(0, u, 2*u, 3*u);
          line(0, 0, 3*u, 3*u);
          line(u, 0, 3*u, 2*u);
          line(2*u, 0, 3*u, u);
        } else {
          line(u, 0, 0, u);
          line(2*u, 0, 0, 2*u);
          line(3*u, 0, 0, 3*u);
          line(3*u, u, u, 3*u);
          line(3*u, 2*u, 2*u, 3*u);
        }
      }

      pop();
    }
  }
}

function keyPressed() {
  if (key === " ") {
    draw();
  }
}
